INSERT INTO "dynasties" ("id","name","alt_names","ethnicity","feudal_rank","scope","region","start_year","start_month","start_day","start_confidence","end_year","end_month","end_day","end_confidence","start_abs","end_abs","color_token","parent_id","group_id","note") VALUES ('roc','中华民国','["中华民国","民国"]',NULL,NULL,'cn','east_asia',1912,1,NULL,'month',1949,10,NULL,'month',22944,23397,'ochre',NULL,NULL,'辛亥革命后，中华民国于1912年建立，先后经历南京临时政府、北京政府、南京国民政府及行宪后的总统制度。民国时期伴随政权更迭、军阀割据、北伐、抗日战争与国共内战；1949年迁往台湾。');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('cai-e','蔡锷','roc','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["军事家"]','近代军事家，字松坡，湖南邵阳人，早年留学日本并参与云南新军建设。1915年云南宣布独立后，他与唐继尧等组织护国军反对袁世凯称帝；后赴日本治病，1916年病逝。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/蔡锷"}]',NULL,NULL,NULL,'[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('cai-tingkai','蔡廷锴','roc','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["军事家"]','国民革命军将领，淞沪抗战期间任第十九路军军长，参与指挥驻沪部队抵抗日军进攻。','[{"label":"上海市民政局：是谁打响“一·二八”淞沪抗战第一枪","url":"https://mzj.sh.gov.cn/lnb-wsws/20220207/97fe1737b42c42ad93b2c426450660f1.html"}]',NULL,NULL,NULL,'[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('cai-yingwen','蔡英文','roc','[]',NULL,NULL,1956,8,NULL,'month',NULL,NULL,NULL,NULL,'["政治家"]','蔡英文是法律与两岸事务学者，曾任行政院副院长及民进党主席，2016年当选台湾地区领导人。任内推动年金改革、能源转型与国防政策调整，并签署同性婚姻法案；2020年连任，2024年卸任。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/蔡英文"}]',NULL,NULL,'','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('cao-kun','曹锟','roc','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["军事家","政治家"]','曹锟是北洋直系军阀首领，曾任直隶督军。1923年通过贿选当选大总统，任内颁行《中华民国宪法》；1924年冯玉祥发动北京政变，曹锟被囚并辞职，北洋政府陷入新一轮权力重组。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/曹锟"}]',NULL,NULL,'大总统','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('chen-gongbo','陈公博','roc','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["政治家"]','汪精卫政权重要成员，曾任立法院长、行政院长。1944年汪精卫赴日治疗后代理汪伪国民政府主席，1945年8月16日宣布解散该政权；抗战胜利后被捕并以汉奸罪审判。','[{"label":"中国抗日战争史：汪精卫建立伪国民政府","url":"https://szzy.7lue.cn/read/eddf364fc59f9d9306913a56193b3e20/2dfe4578f86d60f92960c1df4e84e7b7.md"},{"label":"人民日报党史频道：汪伪政权的最后一天","url":"https://dangshi.people.com.cn/n1/2016/0811/c85037-28628608.html"}]',NULL,NULL,'伪国民政府代主席','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('chen-jiongming','陈炯明','roc','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["军事家","政治家"]','民国政治人物、军事将领，字竞存，广东海丰人。曾任广东都督，支持联省自治与地方自治；1922年与孙中山决裂并炮击总统府，后在粤军攻势下退出广东。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/陈炯明"}]',NULL,NULL,NULL,'[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('chen-shuibian','陈水扁','roc','[]',NULL,NULL,1950,10,NULL,'month',NULL,NULL,NULL,NULL,'["政治家"]','陈水扁曾任台北市长，2000年当选台湾地区领导人，结束国民党长期执政并实现首次和平政党轮替。其两届任内推动“小三通”、社会与司法改革，台湾于2002年加入世界贸易组织；2008年卸任。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/陈水扁"}]',NULL,NULL,'','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('du-xigui','杜锡珪','roc','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["军事家","政治家"]','杜锡珪为海军将领，曾任海军总长和国务总理。1926年颜惠庆内阁解散后，他短暂代理国务总理并以国务院名义摄行大总统职权，随后将权力交由顾维钧内阁。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/杜锡珪"}]',NULL,NULL,'国务院摄行','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('duan-qirui','段祺瑞','roc','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["军事家","政治家"]','段祺瑞是北洋皖系首领，袁世凯时期多次任国务总理。1924年北京政变后出任临时执政，试图召开善后会议、重组政局；其政府在国民会议争议及奉系、直系压力下失势，1926年下台。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/段祺瑞"}]',NULL,NULL,'临时执政','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('feng-guozhang','冯国璋','roc','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["军事家","政治家"]','冯国璋为北洋将领、直系重要人物，曾任副总统。黎元洪离职后，他以副总统代理大总统，并于1917—1918年任总统；其任内南北对立与护法战争持续，卸任后仍参与北洋政局。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/冯国璋"}]',NULL,NULL,'代理大总统','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('feng-yuxiang','冯玉祥','roc','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["军事家"]','北洋及民国时期将领，字焕章，原籍安徽巢县。曾任西北军首领，1924年发动北京政变，促成清帝溥仪出宫并邀请孙中山北上；后参加抗日活动，1948年在苏联返国途中船难遇难。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/冯玉祥"}]',NULL,NULL,NULL,'[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('gao-lingwei','高凌霨','roc','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["政治家"]','高凌霨是北洋政府官员，曾任直隶省长、国务总理。黎元洪第二次离职后，他于1923年短暂以国务院名义摄行大总统职权，随后曹锟就任总统。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/高凌霨"}]',NULL,NULL,'国务院摄行','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('gu-weijun','顾维钧','roc','["V. K. Wellington Koo"]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["外交家","政治家"]','顾维钧是外交家，因巴黎和会拒绝在《凡尔赛条约》上签字而知名，后任国务总理兼外交总长。1926—1927年他主持内阁并以国务院名义摄行大总统职权，安国军政府成立后结束该段职务。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/顾维钧"}]',NULL,NULL,'国务院摄行','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('hu-weide','胡惟德','roc','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["外交家","政治家"]','胡惟德是资深外交官与北洋政府官员，曾任国务总理。段祺瑞下台后，他两度以国务院名义摄行元首职权，分别处于1926年临时执政交接及1927年政府改组期间。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/胡惟德"}]',NULL,NULL,'国务院摄行','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('huang-fu','黄郛','roc','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["政治家"]','黄郛为国民党政治人物，曾任外交总长等职。1924年北京政变后，他短暂以国务院名义摄行大总统职权，并参与迎段祺瑞出任临时执政；此后转入南京国民政府任职。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/黄郛"}]',NULL,NULL,'国务院摄行','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('jiang-guangnai','蒋光鼐','roc','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["军事家"]','国民革命军将领，淞沪抗战期间任第十九路军总指挥，与蔡廷锴等指挥上海守军抵抗日军进攻。','[{"label":"上海市民政局：是谁打响“一·二八”淞沪抗战第一枪","url":"https://mzj.sh.gov.cn/lnb-wsws/20220207/97fe1737b42c42ad93b2c426450660f1.html"}]',NULL,NULL,NULL,'[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('jiang-jieshi','蒋介石','roc','["蒋中正"]',NULL,NULL,1887,10,NULL,'month',1975,4,NULL,'month','["军事家","政治家"]','蒋介石是国民革命军主要领导人，曾任黄埔军校校长并主持北伐。1928年后多次担任南京国民政府主席，抗日战争期间任军事与政府领导职务，1948年当选行宪后首任总统；1949年中央政府迁台后继续执政，1975年去世。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/蒋介石"}]',NULL,NULL,'','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('jiang-jingguo','蒋经国','roc','[]',NULL,NULL,1910,4,NULL,'month',1988,1,NULL,'year','["政治家"]','蒋经国长期参与国民党与政府事务，曾任行政院院长，1978年继任台湾地区领导人。其任内推动十大建设、扩大本地人才参与，并于1987年宣布解除戒严、开放党禁报禁及赴大陆探亲；1988年去世，由李登辉继任。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/蒋经国"}]',NULL,NULL,'','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('lai-qingde','赖清德','roc','[]',NULL,NULL,1959,10,NULL,'month',NULL,NULL,NULL,NULL,'["政治家"]','赖清德曾任立法委员、台南市长、行政院院长及副总统，2024年当选并就任台湾地区领导人。其任期延续于蔡英文之后，面对两岸关系、能源与产业转型等议题。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/赖清德"},{"label":"交接日期复核来源","url":"https://www.president.gov.tw/News/28428"}]',NULL,NULL,'','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('li-denghui','李登辉','roc','[]',NULL,NULL,1923,1,NULL,'year',2020,7,NULL,'month','["政治家"]','李登辉原任副总统，蒋经国去世后继任台湾地区领导人，并于1990年当选。任内推动终止动员戡乱时期、国会全面改选与直选，1996年成为首次全民直选产生的领导人；2000年政党轮替后卸任。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/李登辉"}]',NULL,NULL,'','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('li-yuanhong','黎元洪','roc','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["政治家"]','黎元洪原为湖北新军将领，武昌起义后被推为湖北军政府都督。袁世凯死后他先后两度任大总统，任内与段祺瑞围绕参战、国会及内阁权力发生府院之争；第二任期在直皖冲突后结束。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/黎元洪"}]',NULL,NULL,'大总统','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('li-zongren','李宗仁','roc','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["军事家","政治家"]','李宗仁是桂系将领，抗战期间指挥台儿庄战役，后当选副总统。蒋介石于1949年引退后，他依法代理总统；蒋介石于1950年复行视事，李宗仁随后离开大陆并长期旅居海外。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/李宗仁"}]',NULL,NULL,'代总统','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('lin-sen','林森','roc','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["政治家"]','林森是辛亥革命元老，曾任国民政府委员长（主席）。1931—1943年任主席期间，实际军政决策主要由蒋介石等人掌握；抗日战争期间长期留重庆办公，1943年去世。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/林森"}]',NULL,NULL,'国民政府主席','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('liu-wenhui','刘文辉','roc','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["军事家"]','川系军阀，字自乾，四川大邑人，为刘湘叔父。曾控制川康地区并任西康省主席，抗战后期与刘文辉等参与起义；中华人民共和国成立后任西南军政委员会副主席等职。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/刘文辉"}]',NULL,NULL,NULL,'[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('liu-xiang','刘湘','roc','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["军事家"]','川系军阀，字甫澄，四川大邑人。长期参与四川军阀混战，1933年成为四川主要军事领袖；抗战爆发后任第七战区司令长官，率川军出川抗日，1938年病逝于汉口。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/刘湘"}]',NULL,NULL,NULL,'[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('long-yun','龙云','roc','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["军事家","政治家"]','滇系军阀，字志舟，云南昭通人。1927年发动政变取代唐继尧，长期主政云南；抗战时期接受国民政府任命并支持滇军出征，1945年失去云南军政权力，后赴南京、香港等地。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/龙云"}]',NULL,NULL,NULL,'[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('lu-rongting','陆荣廷','roc','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["军事家"]','民国旧桂系首领，字干卿，广西武鸣人。清末在广西镇压会党起势，曾任广西都督并影响两广政局；护法运动后旧桂系势力衰退，晚年离开政坛。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/陆荣廷"}]',NULL,NULL,NULL,'[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('ma-bufang','马步芳','roc','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["军事家"]','马家军重要首领，字子香，甘肃河州人，长期控制青海军政。抗战时期任国民政府军事委员会委员长西北行营主任等职；1949年赴海外，晚年居于沙特阿拉伯。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/马步芳"}]',NULL,NULL,NULL,'[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('ma-yingjiu','马英九','roc','[]',NULL,NULL,1950,7,NULL,'month',NULL,NULL,NULL,NULL,'["政治家"]','马英九曾任法务部长、台北市长及国民党主席，2008年当选台湾地区领导人，成为政党轮替后的第二位领导人。任内与大陆恢复制度化协商并推动直航、签署《两岸经济合作架构协议》，同时推动地方行政区调整；2016年卸任。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/马英九"}]',NULL,NULL,'','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('sun-chuanfang','孙传芳','roc','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["军事家"]','北洋时期直系军阀，字馨远，山东历城人。1920年代控制福建、浙江、江苏、安徽、江西等地，号称“五省联帅”；北伐军进攻后失去地盘，1935年在天津被刺身亡。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/孙传芳"}]',NULL,NULL,NULL,'[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('tan-yankai','谭延闿','roc','["谭延闓"]',NULL,NULL,1880,1,NULL,'year',1930,9,NULL,'month','["政治家"]','谭延闿是湖南地方政治人物、国民党元老，曾任湖南督军及国民政府要职。宁汉合流后于1928年出任南京国民政府主席，张作霖离京后成为该包所记的主线元首；随后转任行政院院长。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/谭延闿"}]',NULL,NULL,'国民政府主席','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('tang-jiyao','唐继尧','roc','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["军事家","政治家"]','滇系军阀首领，字蓂赓，云南会泽人。辛亥革命后任云南都督，护国战争中支持蔡锷讨袁，后长期控制云南并一度扩展至贵州、四川；1927年被部属政变驱逐。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/唐继尧"}]',NULL,NULL,NULL,'[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('wang-jingwei','汪精卫','roc','["汪兆铭"]',NULL,NULL,NULL,NULL,NULL,NULL,1944,11,NULL,'month','["政治家"]','曾任中国国民党要职，抗战期间脱离重庆国民政府并与日本合作。1940年在南京建立汪伪国民政府，先任代主席、后任主席；1944年赴日治疗并由陈公博代理，11月病逝。','[{"label":"中国抗日战争史：汪精卫建立伪国民政府","url":"https://szzy.7lue.cn/read/eddf364fc59f9d9306913a56193b3e20/2dfe4578f86d60f92960c1df4e84e7b7.md"},{"label":"中国通史：汪精卫国民政府的僭立","url":"https://szzy.7lue.cn/read/5d14e01721b1a1ebbcbf1e7f1/fb899fb6618b6ef45941a56359ca9999.md"}]',NULL,NULL,'伪国民政府主席','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('wu-peifu','吴佩孚','roc','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["军事家"]','北洋时期直系军阀首领，字子玉，山东蓬莱人。曾控制直隶及长江流域部分省份，先后参与直皖、直奉战争，1924年第二次直奉战争失败后失势；抗战期间留居北京，1939年遇刺身亡。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/吴佩孚"}]',NULL,NULL,NULL,'[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('xu-shichang','徐世昌','roc','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["政治家"]','徐世昌是清末翰林出身的北洋政治人物，与袁世凯关系密切。1918年当选大总统，主张停战与“偃武修文”，但南北分裂、军阀割据未能消弭；1922年直系控制北京后辞职。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/徐世昌"}]',NULL,NULL,'大总统','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('yan-huiqing','颜惠庆','roc','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["外交家","政治家"]','颜惠庆是外交官、曾任国务总理。1926年段祺瑞离职后，他主持摄政内阁并以国务院名义短暂摄行大总统职权；奉系与国民军争夺北京政权期间，政府权力迅速更替。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/颜惠庆"}]',NULL,NULL,'国务院摄行','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('yan-jiagan','严家淦','roc','[]',NULL,NULL,1905,10,NULL,'month',1993,12,NULL,'month','["政治家"]','严家淦是财政与行政官员，曾任台湾省政府主席、行政院院长及副总统。蒋介石于1975年去世后，他继任总统至1978年；任内支持行政院推动十大建设，并筹设新竹科学工业园区。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/严家淦"}]',NULL,NULL,'领导人','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('yan-xishan','阎锡山','roc','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["军事家","政治家"]','民国时期晋系首领，字百川，山西五台人。长期主政山西，推行地方建设与军事改革，曾任国民政府要职；抗战期间组织晋绥军，内战后赴台湾，1950年病逝。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/阎锡山"}]',NULL,NULL,NULL,'[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('yuan-shikai','袁世凯','roc','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["政治家","军事家"]','袁世凯出身淮军系统，晚清历任要职并参与新军建设。辛亥革命后接任临时大总统，1913年正式就任；其政府镇压二次革命、解散国民党，1915年称帝引发护国战争，次年取消帝制并去世，北洋政府权力随之分散。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/袁世凯"}]',NULL,NULL,'大总统','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('zhang-xueliang','张学良','roc','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["军事家"]','奉系将领，字汉卿，张作霖之子。1928年张作霖遇刺后接掌东北，宣布东北易帜、归附南京国民政府；1936年与杨虎城发动西安事变，促成国共合作抗日，后长期被软禁。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/张学良"}]',NULL,NULL,NULL,'[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('zhang-zuolin','张作霖','roc','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["军事家","政治家"]','张作霖出身东北地方武装，逐步控制奉天并建立奉系，成为北洋后期重要军政领袖。1927年就任陆海军大元帅并在北京行使最高权力；北伐军推进后撤离北京，1928年在皇姑屯遭日军炸车身亡。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/张作霖"}]',NULL,NULL,'陆海军大元帅','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('zhou-ziqi','周自齐','roc','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["政治家"]','周自齐为北洋政府官员，曾任国务总理。黎元洪辞职后，他于1922年短暂以国务院名义摄行大总统职权，直至黎元洪复任；此段反映当时总统职位与内阁更迭的频繁。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/周自齐"}]',NULL,NULL,'国务院摄行','[]');
