INSERT INTO "events" ("id","name","kind","time_mode","at_confidence","start_confidence","end_confidence","date_note","at_year","at_month","at_day","at_abs","start_year","start_month","start_day","start_abs","end_year","end_month","end_day","end_abs","summary","meaning","content","links") VALUES ('changde-campaign','常德会战','battle','span',NULL,'month','month','1943年11月至12月；常德于12月初失守，月底日军撤退。',NULL,NULL,NULL,NULL,1943,11,NULL,23326,1943,12,NULL,23327,'日军为控制洞庭湖西侧交通并削弱第六战区，于1943年冬进攻常德。守城部队在孤立状态下坚守，常德一度陷落；中国军队随后合围反攻，日军撤出并恢复战前态势。会战中日军大量使用毒气，守城与反攻成为相持阶段湖南战场的重要战事。',NULL,NULL,'[]');
INSERT INTO "events" ("id","name","kind","time_mode","at_confidence","start_confidence","end_confidence","date_note","at_year","at_month","at_day","at_abs","start_year","start_month","start_day","start_abs","end_year","end_month","end_day","end_abs","summary","meaning","content","links") VALUES ('civil-war','解放战争','battle','span',NULL,'year','year',NULL,NULL,NULL,NULL,NULL,1946,1,NULL,23352,1949,12,NULL,23399,'国共内战，三大战役后国民党退守台湾，大陆政权更迭。',NULL,NULL,'[]');
INSERT INTO "events" ("id","name","kind","time_mode","at_confidence","start_confidence","end_confidence","date_note","at_year","at_month","at_day","at_abs","start_year","start_month","start_day","start_abs","end_year","end_month","end_day","end_abs","summary","meaning","content","links") VALUES ('first-changsha-campaign','第一次长沙会战','battle','span',NULL,'month','month','1939年9月至10月；日期依据湖南省档案馆与中国第二历史档案馆整理的湖南战场史料。',NULL,NULL,NULL,NULL,1939,9,NULL,23276,1939,10,NULL,23277,'日军第十一军从赣北、鄂南和湘北进攻，企图消灭第九战区主力并迫使中国政府屈服。薛岳指挥中国军队逐步抵抗、诱敌深入后反击，日军推进至长沙外围后撤退并恢复战前态势；这是相持阶段双方围绕湖南交通与战区主力展开的重要会战。',NULL,NULL,'[]');
INSERT INTO "events" ("id","name","kind","time_mode","at_confidence","start_confidence","end_confidence","date_note","at_year","at_month","at_day","at_abs","start_year","start_month","start_day","start_abs","end_year","end_month","end_day","end_abs","summary","meaning","content","links") VALUES ('hengyang-defense','衡阳保卫战','battle','span',NULL,'month','month','1944年6月下旬至8月上旬；按中国第二历史档案馆专题记录。',NULL,NULL,NULL,NULL,1944,6,NULL,23333,1944,8,NULL,23335,'豫湘桂会战期间，日军围攻衡阳以控制粤汉铁路。第十军军长方先觉指挥守军依托工事顽强抵抗，日军多次进攻受挫；援军未能解围、弹药补给断绝后，衡阳于8月上旬失守。长期守城迟滞了日军推进，也成为豫湘桂战局中抵抗最持久的战斗之一。',NULL,NULL,'[]');
INSERT INTO "events" ("id","name","kind","time_mode","at_confidence","start_confidence","end_confidence","date_note","at_year","at_month","at_day","at_abs","start_year","start_month","start_day","start_abs","end_year","end_month","end_day","end_abs","summary","meaning","content","links") VALUES ('hundred-regiments-campaign','百团大战','battle','span',NULL,'day','month','1940年8月20日发起，战役阶段延续至1941年1月；不同战史对阶段划分有差异。',NULL,NULL,NULL,NULL,1940,8,20,23287,1941,1,NULL,23292,'为破击华北日军交通线、打击据点封锁，八路军在总部统一指挥下发动大规模进攻，重点攻击正太铁路，并扩展至同蒲、平汉等交通线。战役初期参战部队超过百个团，故称“百团大战”；铁路与据点遭到破坏，日军随后加强报复性“扫荡”，敌后战场的作战形态也随之变化。',NULL,NULL,'[{"label":"中国共产党新闻网：百团大战","url":"http://cpc.people.com.cn/GB/64162/64172/85037/85039/6617926.html"}]');
INSERT INTO "events" ("id","name","kind","time_mode","at_confidence","start_confidence","end_confidence","date_note","at_year","at_month","at_day","at_abs","start_year","start_month","start_day","start_abs","end_year","end_month","end_day","end_abs","summary","meaning","content","links") VALUES ('kunlun-pass-battle','昆仑关战役','battle','span',NULL,'month','month','1939年12月至1940年1月；战斗起于12月中旬，昆仑关于1940年1月收复。',NULL,NULL,NULL,NULL,1939,12,NULL,23279,1940,1,NULL,23280,'日军占领南宁后威胁桂越交通与西南后方，中国军队集中力量反攻昆仑关。第五军等部在杜聿明指挥下与日军激战并一度攻克关隘，随后守住战果；战斗迟滞了日军向桂林、柳州方向的推进，成为桂南会战中的关键战役。',NULL,NULL,'[]');
INSERT INTO "events" ("id","name","kind","time_mode","at_confidence","start_confidence","end_confidence","date_note","at_year","at_month","at_day","at_abs","start_year","start_month","start_day","start_abs","end_year","end_month","end_day","end_abs","summary","meaning","content","links") VALUES ('may-fourth','五四运动','politics','point','day',NULL,NULL,'1919年5月4日，北京学生举行集会游行。',1919,5,4,23032,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'巴黎和会决定将德国在山东的权益转交日本，北京学生于天安门集会游行抗议，要求拒签和约并惩办亲日官员；运动随后扩展至全国。',NULL,NULL,'[{"label":"外交部：五四运动","url":"https://www.fmprc.gov.cn/web/ziliao_674904/historytoday_674971/200305/t20030504_9284558.shtml"}]');
INSERT INTO "events" ("id","name","kind","time_mode","at_confidence","start_confidence","end_confidence","date_note","at_year","at_month","at_day","at_abs","start_year","start_month","start_day","start_abs","end_year","end_month","end_day","end_abs","summary","meaning","content","links") VALUES ('mukden-incident','九一八事变','battle','point','day',NULL,NULL,'1931年9月18日夜，关东军在沈阳柳条湖制造铁路爆炸并进攻北大营。',1931,9,18,23180,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'关东军在沈阳柳条湖附近炸毁南满铁路路轨，并诬称中国军队所为，随即进攻北大营和沈阳；日军随后扩大侵占东北。',NULL,NULL,'[{"label":"人民网党史：九一八事变","url":"https://dangshi.people.com.cn/n/2015/0918/c85037-27604904.html"}]');
INSERT INTO "events" ("id","name","kind","time_mode","at_confidence","start_confidence","end_confidence","date_note","at_year","at_month","at_day","at_abs","start_year","start_month","start_day","start_abs","end_year","end_month","end_day","end_abs","summary","meaning","content","links") VALUES ('nanchang-campaign','南昌会战','battle','span',NULL,'month','month','1939年3月至5月；南昌于3月27日失守，反攻延续至5月。',NULL,NULL,NULL,NULL,1939,3,NULL,23270,1939,5,NULL,23272,'为控制浙赣铁路并巩固武汉外围，日军于1939年春进攻南昌。中国军队在修水、南昌及周边地区抵抗，南昌于3月下旬失守，随后中国军队发动反攻但未能收复城市；会战反映出相持阶段日军仍持续争夺交通线和战略据点。',NULL,NULL,'[]');
INSERT INTO "events" ("id","name","kind","time_mode","at_confidence","start_confidence","end_confidence","date_note","at_year","at_month","at_day","at_abs","start_year","start_month","start_day","start_abs","end_year","end_month","end_day","end_abs","summary","meaning","content","links") VALUES ('national-protection-war','护国战争','battle','span',NULL,'year','year','1915–1916年，蔡锷等讨袁',NULL,NULL,NULL,NULL,1915,12,NULL,22991,1916,6,NULL,22997,'蔡锷、唐继尧等起兵讨袁，袁世凯称帝失败。',NULL,NULL,'[]');
INSERT INTO "events" ("id","name","kind","time_mode","at_confidence","start_confidence","end_confidence","date_note","at_year","at_month","at_day","at_abs","start_year","start_month","start_day","start_abs","end_year","end_month","end_day","end_abs","summary","meaning","content","links") VALUES ('northeast-flag-change','东北易帜','politics','point','day',NULL,NULL,'1928年12月29日，张学良通电服从南京国民政府并改悬国旗。',1928,12,29,23147,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'张学良改悬青天白日满地红旗并通电服从南京国民政府，北伐至此结束，南北名义统一；东北仍保留相当地方自主。',NULL,NULL,'[{"label":"辽宁省档案馆：东北易帜和东北新建设","url":"https://www.lnds.com.cn/lnds/cgzs/jzln/4D8DC4718FE74772AE454010629BAD7C/index.shtml"}]');
INSERT INTO "events" ("id","name","kind","time_mode","at_confidence","start_confidence","end_confidence","date_note","at_year","at_month","at_day","at_abs","start_year","start_month","start_day","start_abs","end_year","end_month","end_day","end_abs","summary","meaning","content","links") VALUES ('northern-expedition','北伐战争','battle','span',NULL,'year','year',NULL,NULL,NULL,NULL,NULL,1926,7,NULL,23118,1928,12,NULL,23147,'国民革命军自广州北伐，推翻北洋军阀，统一全国。',NULL,NULL,'[]');
INSERT INTO "events" ("id","name","kind","time_mode","at_confidence","start_confidence","end_confidence","date_note","at_year","at_month","at_day","at_abs","start_year","start_month","start_day","start_abs","end_year","end_month","end_day","end_abs","summary","meaning","content","links") VALUES ('pingjin-campaign','平津作战','battle','span',NULL,'month','month','1937年7月至8月；各地战斗与撤退日期不一，按战事阶段记月。',NULL,NULL,NULL,NULL,1937,7,NULL,23250,1937,8,NULL,23251,'七七事变后，日军向平津地区扩大进攻，国民政府军与第二十九军等部在北平、天津及南苑一带抵抗。北平、天津先后失守，华北战事迅速扩大；这场作战揭示局部冲突已演变为全面战争。',NULL,NULL,'[]');
INSERT INTO "events" ("id","name","kind","time_mode","at_confidence","start_confidence","end_confidence","date_note","at_year","at_month","at_day","at_abs","start_year","start_month","start_day","start_abs","end_year","end_month","end_day","end_abs","summary","meaning","content","links") VALUES ('pingxingguan-battle','平型关战斗','battle','point','day',NULL,NULL,'1937年9月25日；与平型关正面防御作战相关，但两者不是同一场战斗。',1937,9,25,23252,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'太原会战期间，八路军第115师在山西灵丘平型关附近伏击日军辎重部队，配合第二战区阻击行动。战斗缴获物资并打击日军推进，其胜利提振了全国抗战信心。',NULL,NULL,'[]');
INSERT INTO "events" ("id","name","kind","time_mode","at_confidence","start_confidence","end_confidence","date_note","at_year","at_month","at_day","at_abs","start_year","start_month","start_day","start_abs","end_year","end_month","end_day","end_abs","summary","meaning","content","links") VALUES ('puyi-leaves-forbidden-city','溥仪出宫','politics','point','day',NULL,NULL,'1924年11月5日，国民军将溥仪逐出紫禁城',1924,11,5,23098,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'冯玉祥北京政变后执行修正清室优待条件，溥仪被逐出紫禁城，逊清小朝廷终结。',NULL,NULL,'[]');
INSERT INTO "events" ("id","name","kind","time_mode","at_confidence","start_confidence","end_confidence","date_note","at_year","at_month","at_day","at_abs","start_year","start_month","start_day","start_abs","end_year","end_month","end_day","end_abs","summary","meaning","content","links") VALUES ('resistance-war','抗日战争','battle','span',NULL,'year','year','1937–1945年，全面抗战',NULL,NULL,NULL,NULL,1937,7,NULL,23250,1945,9,NULL,23348,'全民族抗战，1945年日本投降，台湾光复。',NULL,NULL,'[]');
INSERT INTO "events" ("id","name","kind","time_mode","at_confidence","start_confidence","end_confidence","date_note","at_year","at_month","at_day","at_abs","start_year","start_month","start_day","start_abs","end_year","end_month","end_day","end_abs","summary","meaning","content","links") VALUES ('roc-mainland-end','国民政府迁台','politics','point','month',NULL,NULL,'1949年12月，中央迁台北，大陆时期结束',1949,12,NULL,23399,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'解放军渡江后国民党退守台湾，中华民国大陆时期终结。',NULL,NULL,'[]');
INSERT INTO "events" ("id","name","kind","time_mode","at_confidence","start_confidence","end_confidence","date_note","at_year","at_month","at_day","at_abs","start_year","start_month","start_day","start_abs","end_year","end_month","end_day","end_abs","summary","meaning","content","links") VALUES ('second-changsha-campaign','第二次长沙会战','battle','span',NULL,'month','month','1941年9月至10月；按湖南战场史料所载会战阶段记月。',NULL,NULL,NULL,NULL,1941,9,NULL,23300,1941,10,NULL,23301,'日军第十一军再次进攻长沙，企图重创第九战区并迫使中国方面妥协。薛岳指挥守军在湘北阻击并反攻，日军一度突入长沙后因补给和后方受威胁而撤退，未能达成作战目标；会战显示日军仍试图以局部攻势改变相持态势。',NULL,NULL,'[]');
INSERT INTO "events" ("id","name","kind","time_mode","at_confidence","start_confidence","end_confidence","date_note","at_year","at_month","at_day","at_abs","start_year","start_month","start_day","start_abs","end_year","end_month","end_day","end_abs","summary","meaning","content","links") VALUES ('shanghai-campaign-1937','淞沪会战','battle','span',NULL,'month','month',NULL,NULL,NULL,NULL,NULL,1937,8,NULL,23251,1937,11,NULL,23254,'1937年8月，国民政府军在上海主动投入大规模作战，试图牵制日军并争取国际关注。双方围绕闸北、江湾、大场及沿海登陆地持续激战，中国军队坚守三个月后因日军增援登陆而撤退，上海失守；会战粉碎了日方速胜预期，也使战争迅速扩展。',NULL,NULL,'[]');
INSERT INTO "events" ("id","name","kind","time_mode","at_confidence","start_confidence","end_confidence","date_note","at_year","at_month","at_day","at_abs","start_year","start_month","start_day","start_abs","end_year","end_month","end_day","end_abs","summary","meaning","content","links") VALUES ('shanghai-incident-1932','一·二八淞沪抗战','battle','span',NULL,'day','day','以1932年1月28日战事爆发至3月3日停战记录作战区间；5月5日签署《淞沪停战协定》，结束后续停战交涉。',NULL,NULL,NULL,NULL,1932,1,28,23184,1932,3,3,23186,'九一八事变后，中日关系持续紧张，上海的抵制日货风潮及日方挑衅使局势升级。1932年1月28日晚，日军突袭上海闸北，第十九路军在蒋光鼐、蔡廷锴等指挥下抵抗，随后第五军增援，战事扩展至吴淞等地；在上海民众支援与国际调停下，交战于3月3日停战，5月5日签署《淞沪停战协定》。此战阻止日军迅速占领上海，但协定限制中国军队在上海周边的部署。',NULL,NULL,'[]');
INSERT INTO "events" ("id","name","kind","time_mode","at_confidence","start_confidence","end_confidence","date_note","at_year","at_month","at_day","at_abs","start_year","start_month","start_day","start_abs","end_year","end_month","end_day","end_abs","summary","meaning","content","links") VALUES ('taierzhuang-battle','台儿庄战役','battle','span',NULL,'day','day','1938年3月23日至4月7日；中国第二历史档案馆档案专题采用此战斗区间。',NULL,NULL,NULL,NULL,1938,3,23,23258,1938,4,7,23259,'徐州会战中，日军沿津浦线南下争夺台儿庄。第五战区司令长官李宗仁调集部队防守，并组织侧翼反击；中国军队在台儿庄及其周边与日军反复争夺，迫使日军撤退。这是全面抗战以来正面战场的重要胜利，显著鼓舞了全国抗战士气。',NULL,NULL,'[{"label":"盐田档案与史志信息网：台儿庄大战开始","url":"https://www.yantian.gov.cn/ytdayszxxw/lsjt/content/post_11737199.html"},{"label":"国家档案局：台儿庄战役档案专题","url":"https://www.saac.gov.cn/zt/2014-09/03/content_65286.htm"}]');
INSERT INTO "events" ("id","name","kind","time_mode","at_confidence","start_confidence","end_confidence","date_note","at_year","at_month","at_day","at_abs","start_year","start_month","start_day","start_abs","end_year","end_month","end_day","end_abs","summary","meaning","content","links") VALUES ('taiyuan-campaign','太原会战','battle','span',NULL,'month','month','1937年9月至11月；不同战史对会战起讫界定略有差异，按战役阶段记月。',NULL,NULL,NULL,NULL,1937,9,NULL,23252,1937,11,NULL,23254,'日军沿平绥、同蒲等方向进攻山西，第二战区依托长城、平型关、忻口及太原外围组织防御。平型关、忻口等战斗迟滞日军，但日军从娘子关方向突破后，太原于11月失守，山西正面防线瓦解；会战由此成为华北战局的重要转折。',NULL,NULL,'[]');
INSERT INTO "events" ("id","name","kind","time_mode","at_confidence","start_confidence","end_confidence","date_note","at_year","at_month","at_day","at_abs","start_year","start_month","start_day","start_abs","end_year","end_month","end_day","end_abs","summary","meaning","content","links") VALUES ('third-changsha-campaign','第三次长沙会战','battle','span',NULL,'month','month','1941年12月至1942年1月；湖南省档案馆与中国第二历史档案馆战场史料记载会战起讫。',NULL,NULL,NULL,NULL,1941,12,NULL,23303,1942,1,NULL,23304,'太平洋战争爆发后，日军为牵制中国军队并打通粤汉铁路，再度进攻长沙。第九战区以一部守城、主力在外围反击，长沙守军顶住日军猛攻后，中国军队于1942年1月转入反攻，日军撤退至新墙河以北；此次胜利提升了盟国对中国战场的关注。',NULL,NULL,'[]');
INSERT INTO "events" ("id","name","kind","time_mode","at_confidence","start_confidence","end_confidence","date_note","at_year","at_month","at_day","at_abs","start_year","start_month","start_day","start_abs","end_year","end_month","end_day","end_abs","summary","meaning","content","links") VALUES ('warlord-era','军阀割据','politics','span',NULL,'year','year','1916年袁死至1928年东北易帜，北洋诸系及地方军阀混战',NULL,NULL,NULL,NULL,1916,1,NULL,22992,1928,1,NULL,23136,'北洋分裂，直皖直奉混战，地方割据，中央名义大于实权。',NULL,NULL,'[]');
INSERT INTO "events" ("id","name","kind","time_mode","at_confidence","start_confidence","end_confidence","date_note","at_year","at_month","at_day","at_abs","start_year","start_month","start_day","start_abs","end_year","end_month","end_day","end_abs","summary","meaning","content","links") VALUES ('western-hunan-campaign','湘西会战','battle','span',NULL,'month','month','1945年4月至6月；又称雪峰山战役，具体起讫日期依不同战史略有差异。',NULL,NULL,NULL,NULL,1945,4,NULL,23343,1945,6,NULL,23345,'日军为夺取芷江机场、改善在华战局，向湘西发动进攻。中国军队依托雪峰山地形防御并转入反击，日军在连续战斗后撤退，未能攻占芷江；这是中国正面战场由防御转入反攻的重要会战，也是日本投降前中国战场最后一场大型会战。',NULL,NULL,'[]');
INSERT INTO "events" ("id","name","kind","time_mode","at_confidence","start_confidence","end_confidence","date_note","at_year","at_month","at_day","at_abs","start_year","start_month","start_day","start_abs","end_year","end_month","end_day","end_abs","summary","meaning","content","links") VALUES ('wuhan-campaign','武汉会战','battle','span',NULL,'month','month','1938年6月至10月；武汉于10月25日被日军占领，按月记录会战区间。',NULL,NULL,NULL,NULL,1938,6,NULL,23261,1938,10,NULL,23265,'南京失守后，武汉成为中国重要政治、军事中心。日军自长江南北多路进攻，国民政府军在大别山、长江沿线及万家岭等地节节抵抗；万家岭取得局部胜利，但武汉最终于10月失守。大规模抵抗迟滞日军攻势，标志战争由战略防御转入相持阶段。',NULL,NULL,'[]');
INSERT INTO "events" ("id","name","kind","time_mode","at_confidence","start_confidence","end_confidence","date_note","at_year","at_month","at_day","at_abs","start_year","start_month","start_day","start_abs","end_year","end_month","end_day","end_abs","summary","meaning","content","links") VALUES ('xi-an-incident','西安事变','politics','point','day',NULL,NULL,'1936年12月12日，张学良、杨虎城在西安发动兵谏并扣留蒋介石。',1936,12,12,23243,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'张学良、杨虎城为迫蒋介石停止内战、联共抗日，于西安扣留蒋介石；事变经谈判和平解决，成为第二次国共合作的重要转折。',NULL,NULL,'[{"label":"人民网党史：西安事变","url":"https://cpc.people.com.cn/GB/33837/2534330.html"}]');
INSERT INTO "events" ("id","name","kind","time_mode","at_confidence","start_confidence","end_confidence","date_note","at_year","at_month","at_day","at_abs","start_year","start_month","start_day","start_abs","end_year","end_month","end_day","end_abs","summary","meaning","content","links") VALUES ('xinkou-battle','忻口战役','battle','span',NULL,'day','day','忻口正面战斗于1937年10月13日开始，战线在11月上旬撤退。',NULL,NULL,NULL,NULL,1937,10,13,23253,1937,11,2,23254,'日军突破内长城防线后，第二战区在忻口组织防御，由阎锡山统筹、卫立煌等指挥前线部队，八路军在日军侧后开展袭扰以配合作战。双方在阵地攻防中持续激战，守军最终因娘子关方向失守及太原受威胁而撤退；这是国共军队协同抗战的重要战例。',NULL,NULL,'[{"label":"国家档案局：档案里的中国抗战·忻口战役","url":"https://www.saac.gov.cn/zt/2014-08/29/content_64741.htm"},{"label":"北京市委统战部：忻口战役","url":"https://www.bjtzb.gov.cn/wwwroot/sdtyzx/publish/article/42/202/213/214/22894.shtml"}]');
INSERT INTO "events" ("id","name","kind","time_mode","at_confidence","start_confidence","end_confidence","date_note","at_year","at_month","at_day","at_abs","start_year","start_month","start_day","start_abs","end_year","end_month","end_day","end_abs","summary","meaning","content","links") VALUES ('xuzhou-campaign','徐州会战','battle','span',NULL,'month','month','1938年初至5月徐州撤退；各战斗跨多个省份且起讫口径不一。',NULL,NULL,NULL,NULL,1938,1,NULL,23256,1938,5,NULL,23260,'日军为打通津浦铁路、连接南北战场，分别由山东和长江下游向徐州合击。中国军队在临沂、台儿庄等地阻击后撤出徐州，避免被合围；日军虽占领徐州，却未能围歼中国主力，随后在武汉方向继续推进。台儿庄战役是徐州会战中的关键胜利，另作独立事件记录。',NULL,NULL,'[]');
INSERT INTO "events" ("id","name","kind","time_mode","at_confidence","start_confidence","end_confidence","date_note","at_year","at_month","at_day","at_abs","start_year","start_month","start_day","start_abs","end_year","end_month","end_day","end_abs","summary","meaning","content","links") VALUES ('yuan-shikai-emperor','袁世凯接受帝位推戴','politics','point','day',NULL,NULL,'1915年12月12日接受国民代表推戴；1916年3月22日取消帝制，未举行登基典礼。',1915,12,12,22991,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'袁世凯接受国民代表推戴，筹备改行君主制并以中华帝国为号；护国战争与各省反对使其于1916年3月取消帝制，未举行登基典礼。',NULL,NULL,'[{"label":"民国历史纪要：中华帝国与袁世凯称帝","url":"https://www.rocmgov.org/rocevents"}]');
INSERT INTO "events" ("id","name","kind","time_mode","at_confidence","start_confidence","end_confidence","date_note","at_year","at_month","at_day","at_abs","start_year","start_month","start_day","start_abs","end_year","end_month","end_day","end_abs","summary","meaning","content","links") VALUES ('yuxianggui-campaign','豫湘桂会战','battle','span',NULL,'month','month','1944年春至冬，分豫中、长衡、桂柳等阶段；按整体作战年度记载。',NULL,NULL,NULL,NULL,1944,4,NULL,23331,1944,12,NULL,23339,'日本为打通大陆交通线、连接华北与越南方向，发动“一号作战”，中国方面称豫湘桂会战。日军先后进攻河南、湖南、广西，攻占多座城市和机场；中国军队在局部战场持续抵抗，但整体防线严重崩溃，日军获得交通线并造成大规模难民流离。长衡会战及衡阳保卫战是其中的重要阶段，另作独立事件记录。',NULL,NULL,'[]');
